<?php require_once __DIR__.'/lib/inicio.php';exigir_sesion();if(!es_control())exit('No autorizado');if(!class_exists('ZipArchive'))exit('Habilite la extensión ZIP de PHP.');$casos=isset($_GET['todos'])?bd()->query('SELECT * FROM casos_actualizacion ORDER BY id_caso')->fetch_all(MYSQLI_ASSOC):[obtener_caso((int)$_GET['id'])];$tmp=tempnam(sys_get_temp_dir(),'sccmgpc');$z=new ZipArchive;$z->open($tmp,ZipArchive::OVERWRITE);foreach($casos as $c){$carpeta=$c['folio'];$z->addFromString("$carpeta/datos_del_caso.json",json_encode($c,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));$s=bd()->prepare('SELECT * FROM archivos_caso WHERE id_caso=?');$s->bind_param('i',$c['id_caso']);$s->execute();$r=$s->get_result();while($a=$r->fetch_assoc())$z->addFromString("$carpeta/archivos/".$a['id_archivo'].'_'.basename($a['nombre_original']),$a['contenido']);}$z->close();header('Content-Type: application/zip');header('Content-Disposition: attachment; filename="expedientes_sccmgpc.zip"');readfile($tmp);unlink($tmp);